command:
python3 -c 'import sys, os, json, csv; s1, s2, out = "${answer1}", "${answer2}", "${answer3}" or "users_difference_report.csv";
def resolve(p): return p if os.path.exists(p) else (f"snapshots/users_snapshot_{p}.json" if os.path.exists(f"snapshots/users_snapshot_{p}.json") else p);
s1, s2 = resolve(s1), resolve(s2);
u1 = {u["id"]: u for u in json.load(open(s1))} if os.path.exists(s1) else {};
u2 = {u["id"]: u for u in json.load(open(s2))} if os.path.exists(s2) else {};
rows = [];
[rows.append(["DELETED", uid, u.get("profile",{}).get("firstName",""), u.get("profile",{}).get("lastName",""), u.get("profile",{}).get("email",""), u.get("profile",{}).get("login",""), u.get("status",""), "Removed"]) for uid, u in u1.items() if uid not in u2];
[rows.append(["ADDED", uid, u.get("profile",{}).get("firstName",""), u.get("profile",{}).get("lastName",""), u.get("profile",{}).get("email",""), u.get("profile",{}).get("login",""), u.get("status",""), "Added"]) for uid, u in u2.items() if uid not in u1];
for uid, u in u1.items():
    if uid in u2:
        p1, p2 = u.get("profile",{}), u2[uid].get("profile",{});
        diffs = [f"{k}: {p1.get(k)} -> {p2.get(k)}" for k in set(p1)|set(p2) if p1.get(k) != p2.get(k)];
        if diffs: rows.append(["MODIFIED", uid, p2.get("firstName",""), p2.get("lastName",""), p2.get("email",""), p2.get("login",""), u2[uid].get("status",""), "; ".join(diffs)]);
out_path = out if out.endswith((".csv", ".xlsx")) else f"{out}.csv";
with open(out_path, "w", newline="") as f: w = csv.writer(f); w.writerow(["Change Type", "User ID", "First Name", "Last Name", "Email", "Login", "Status", "Details"]); w.writerows(rows);
print(json.dumps({"excel_file": out_path, "deleted_count": sum(1 for r in rows if r[0]=="DELETED"), "added_count": sum(1 for r in rows if r[0]=="ADDED"), "modified_count": sum(1 for r in rows if r[0]=="MODIFIED"), "total_changes": len(rows)}))'
